import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"模板解析","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"模板解析 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/design/template-resolver"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/design/template-resolver"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/template-resolver"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/template-resolver"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/template-resolver"}]]},"headers":[],"relativePath":"zh/clice/design/template-resolver.md","filePath":"zh/clice/design/template-resolver.md","lastUpdated":1794738697000}'),o={name:"zh/clice/design/template-resolver.md"};function l(n,e,c,d,r,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="template-resolution" tabindex="-1"><span id="模板解析" class="heading-alias"></span>模板解析 <a class="header-anchor" href="#template-resolution" aria-label="Permalink to &quot;模板解析&quot;">​</a></h1><h2 id="background" tabindex="-1"><span id="背景" class="heading-alias"></span>背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>在模板内部，依赖模板参数的名称要等模板实例化后才有确定的含义：编译器不会解析它，语言服务器面对的便是一片盲区。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typename</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    rows[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // what is rows[0]?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>rows[0]</code> 的类型是 <code>std::vector&lt;std::vector&lt;T&gt;&gt;::reference</code>——标准库通过多层别名、偏特化（partial specialization）和默认实参定义的依赖名：<code>reference</code> → <code>allocator_traits&lt;Alloc&gt;::value_type</code> → ……。clangd 用户长期遇到模板体内代码补全和悬停失效的问题，原因在于 clangd 解析这类名称时的三处局限：</p><ul><li><strong>不处理偏特化。</strong> 它只在主模板中查找成员，而主模板甚至未必声明了这些成员：<code>allocator_traits</code> 就是在特化中定义它们的。</li><li><strong>没有实参映射。</strong> 在 <code>allocator_traits&lt;Alloc&gt;</code> 中查到的成员仍以 <code>Alloc</code> 表示，而不是调用方的 <code>T</code>。</li><li><strong>不展开默认实参。</strong> <code>std::vector&lt;T&gt;</code> 实为 <code>std::vector&lt;T, std::allocator&lt;T&gt;&gt;</code>；依赖默认实参的名称会保持未解析状态。</li></ul><h2 id="design" tabindex="-1"><span id="设计" class="heading-alias"></span>设计 <a class="header-anchor" href="#design" aria-label="Permalink to &quot;设计&quot;">​</a></h2><h3 id="pseudo-instantiation" tabindex="-1"><span id="伪实例化" class="heading-alias"></span>伪实例化 <a class="header-anchor" href="#pseudo-instantiation" aria-label="Permalink to &quot;伪实例化&quot;">​</a></h3><p>clice 无需具体实参即可解析依赖名。它不必知道 <code>T</code> 是 <code>int</code> 还是 <code>string</code>，而是追踪 <code>T</code> 如何在别名链中传递，并用 <code>T</code> 表示最终结果：<code>std::vector&lt;std::vector&lt;T&gt;&gt;::reference</code> 化简为 <code>std::vector&lt;T&gt;&amp;</code>，既具体到足以补全成员，又保留了 <code>T</code> 的符号形式。</p><p>解析器是独立实现的类型重写器，既不使用 Sema，也不使用 Clang 的 <code>TreeTransform</code>——这两者都假定存在带具体实参的真实实例化，而这里恰恰没有。解析器按两种策略运行：<strong>解析（resolve）</strong>负责名称查找——查找依赖成员、依赖模板、形参的绑定值或默认值，以及变量或调用的 <code>decltype</code>；<strong>替换（substitute）</strong>只做形参替换和别名展开。解析策略将别名展开委托给替换策略，因此一次查找绝不会通过某个别名触发又指回自身的另一次查找。</p><h3 id="parameters-and-specializations" tabindex="-1"><span id="形参与特化" class="heading-alias"></span>形参与特化 <a class="header-anchor" href="#parameters-and-specializations" aria-label="Permalink to &quot;形参与特化&quot;">​</a></h3><p>嵌套模板会在多个层级绑定形参，解析器将其维护为一组栈帧；形参在声明它的那个模板的栈帧中查找，因此形参深度相同的两个模板绝不会混用彼此的形参。没有绑定值的形参取其默认值。</p><p>在 <code>A&lt;T&gt;</code> 中查找成员时，解析器自己做模板实参推导：将实参与各个偏特化的模式逐一匹配，选出最匹配的特化（若无匹配则回退到主模板），在其中及其基类中查找该成员，再将查到的类型映射回调用方的实参。正因如此，即使主模板什么也没有声明，也能解析出 <code>allocator_traits&lt;allocator&lt;T&gt;&gt;::value_type</code>。</p><p>标准库类型特征（type traits）中的 <code>type</code>（涵盖 <code>conditional</code>、<code>enable_if</code>、<code>type_identity</code>、<code>remove_*</code> 与 <code>add_*</code> 系列以及 <code>decay</code>）和 <code>value</code>（涵盖 <code>conjunction</code>、<code>disjunction</code> 与 <code>negation</code>）直接按标准规定的规则给出结果：各家标准库都用各自的偏特化来实现它们，每次查询都去推导那些偏特化既耗费开销，算出的结果又完全一致。</p><p>类型全程保留源码中的写法：形参按代码写出的形式绑定实参（是 <code>std::string</code>，而不是 <code>std::basic_string&lt;char, …&gt;</code>），结果也按名称显示形参。</p><h3 id="degrading-gracefully" tabindex="-1"><span id="优雅降级" class="heading-alias"></span>优雅降级 <a class="header-anchor" href="#degrading-gracefully" aria-label="Permalink to &quot;优雅降级&quot;">​</a></h3><p>任何一步失败——查找无果、遇到循环或预算耗尽——都会原样返回依赖名，绝不报错，因此解析最坏也不会比不解析更糟。循环在三处截断：解析一个正在解析中的名称、在已经在查找某名称的类模板中再次查找该名称（CRTP），以及推导其初始化器依赖自身类型的 <code>auto</code>。每次查询还对嵌套深度和总步数设有上限。</p><h2 id="instantiations-as-implementations" tabindex="-1"><span id="将实例化视为实现" class="heading-alias"></span>将实例化视为实现 <a class="header-anchor" href="#instantiations-as-implementations" aria-label="Permalink to &quot;将实例化视为实现&quot;">​</a></h2><p>伪实例化根据写下的模板代码推断依赖名可能表示什么，而翻译单元中的实际实例化则给出了它在每组实参下确实表示什么。clice 将模板视为接口，将它的各个实例化视为实现，正如虚函数与重写它的函数之间的关系：</p><ul><li><strong>语义 Token</strong> 也会读取实例化后的代码：实例化复用了模板的源码位置，因此其解析结果会落到模板中写下的那个 Token 上。若各实例化对该名称的种类达成一致，则保留该种类及它们共有的修饰符；若不一致，则标为 <code>conflict</code>。</li><li><strong>悬停与内联提示</strong>在当前翻译单元只实例化过一次的函数模板内会显示那次实例化的实参；只实例化过一次的类模板中的 <code>auto</code> 变量也会按该次实例化推导类型；若有多次实例化，形参则保持源码中的写法。</li><li><strong>代码导航</strong>会读取每一个实例化：索引记录了每个实例化在模板文本中解析出的结果，因此无论文件是否打开，在依赖名上执行跳转到定义、查找引用、调用层次结构和跳转到实现，都会列出各个实例化的解析结果。</li><li><strong>代码补全</strong>只解析到光标位置，尚未读到后面调用模板的代码；因此模板本身无法确定的成员访问或限定名会再编译一次整个缓冲区，提供所有实例化共有的名称。</li></ul><p>每个位置只生成单个条目的功能——内联提示、折叠范围和大纲——会跳过实例化后的代码：实例化在那里只会重复模板已给出的结果，或者与之冲突。</p><h2 id="design-decisions" tabindex="-1"><span id="设计决策" class="heading-alias"></span>设计决策 <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;设计决策&quot;">​</a></h2><ul><li><strong>为什么不执行真实实例化？</strong> 真实实例化需要具体实参，而模板内部并没有具体实参；何况正在编辑的代码往往还不完整，根本无法实例化。</li><li><strong>为什么分两种策略？</strong> 如果展开别名可以触发名称查找，而查找结果又需要展开别名，两者就会相互递归。替换策略绝不执行查找。</li><li><strong>为什么按规则直接给出标准类型特征的结果？</strong> 它们是实际代码里最常见的依赖类型，各家标准库的写法各不相同，而语言标准已经固定了它们的答案。</li></ul><h2 id="known-limitations" tabindex="-1"><span id="已知限制" class="heading-alias"></span>已知限制 <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><p>解析器只推导源码本身足以确定的部分，其余部分保持未解析而不做猜测：</p><ul><li><strong>含依赖操作数的表达式。</strong> 值表达式在操作数已知时会常量折叠（如计算 <code>N + 1</code>，其中 <code>N</code> 已知），也能与写法相同的模式匹配（如 <code>trait&lt;X, X + 1&gt;</code> 匹配 <code>trait&lt;N, N + 1&gt;</code>）；无法证明相等的表达式保持依赖状态。含依赖操作数的算术表达式（如 <code>value + 1</code>）不推导其类型；下标、<code>-&gt;</code>、<code>*</code> 以及运算符调用则可以解析。</li><li><strong>代码尚未确定的分支。</strong> 依赖未知实参的约束、互不比对方更特化的两个偏特化、通过 <code>decltype</code> 指代自身的基类，以及实参依赖查找（ADL）需要依赖实参才能完成的调用的 <code>decltype</code>，都会让名称保持依赖状态——除非所有候选项给出相同的答案。</li><li><strong>由主模板给出初值的值特征。</strong> 只在显式特化（explicit specialization）中才为 <code>true</code> 的值会折叠为主模板的值：libstdc++ 中 <code>is_integral&lt;T&gt;::value</code> 的主模板值为 <code>false</code>，因此 <code>conditional_t&lt;is_integral_v&lt;T&gt;, A, B&gt;</code> 会像已经确定一样显示为 <code>B</code>。</li><li><strong>靠引用绑定区分的重载。</strong> 若一组重载仅在实参或对象的绑定方式上有别——例如 <code>const U&amp;&amp;</code> 对 <code>const int&amp;</code>、以不带 <code>const</code> 的方式绑定对象的成员模板对 <code>const</code> 成员函数，或显式对象形参（explicit object parameter）——解析器可能选出与编译器不同的重载，或者不选任何重载。</li></ul>`,26)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
